import React, { useEffect, useState } from "react";

function Facilities() {
  const [facilities, setFacilities] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:8081/facilities")
      .then((res) => res.json())
      .then((data) => {
        setFacilities(data);
        setLoading(false);
      })
      .catch((err) => {
        console.error("Error fetching facilities:", err);
        setLoading(false);
      });
  }, []);

  return (
    <div style={styles.page}>
      <div style={styles.card}>
        <h1 style={styles.title}>Our Facilities</h1>

        {loading ? (
          <p style={styles.message}>Loading facilities...</p>
        ) : facilities.length === 0 ? (
          <p style={styles.message}>No facilities found.</p>
        ) : (
          <div style={{ overflowX: "auto" }}>
            <table style={styles.table}>
              <thead>
                <tr>
                  <th style={styles.th}>🏢 Name</th>
                  <th style={styles.th}>📍 Address</th>
                  <th style={styles.th}>🏙 City</th>
                  <th style={styles.th}>🌎 State</th>
                  <th style={styles.th}>📮 Zip Code</th>
                  <th style={styles.th}>🅿 Slots</th>
                  <th style={styles.th}>📞 Contact</th>
                </tr>
              </thead>
              <tbody>
                {facilities.map((facility) => (
                  <tr key={facility.facilityId} style={styles.tr}>
                    <td style={styles.td}>{facility.facilityName}</td>
                    <td style={styles.td}>{facility.address}</td>
                    <td style={styles.td}>{facility.city}</td>
                    <td style={styles.td}>{facility.state}</td>
                    <td style={styles.td}>{facility.zipCode}</td>
                    <td style={styles.td}>{facility.totalSlots}</td>
                    <td style={styles.td}>{facility.contactInfo || "-"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

const styles = {
  page: {
    minHeight: "100vh",
    background: "linear-gradient(120deg, #ffecd2, #fcb69f)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    padding: "20px",
  },
  card: {
    backgroundColor: "#ffffff",
    padding: "30px",
    borderRadius: "20px",
    boxShadow: "0 10px 25px rgba(0,0,0,0.1)",
    width: "100%",
    maxWidth: "1000px",
  },
  title: {
    textAlign: "center",
    fontSize: "2rem",
    color: "#ff7e5f",
    marginBottom: "25px",
    fontWeight: "bold",
  },
  message: {
    textAlign: "center",
    color: "#777",
  },
  table: {
    width: "100%",
    borderCollapse: "separate",
    borderSpacing: "0 8px",
  },
  th: {
    backgroundColor: "#ff7e5f",
    color: "#fff",
    padding: "12px 15px",
    textAlign: "left",
    borderTopLeftRadius: "8px",
    borderTopRightRadius: "8px",
  },
  td: {
    backgroundColor: "#fff6f3",
    padding: "12px 15px",
    borderRadius: "8px",
    boxShadow: "0 2px 6px rgba(0,0,0,0.05)",
  },
  tr: {
    transition: "transform 0.2s ease",
    cursor: "pointer",
  },
};

export default Facilities;
